  OPTIONAL { ?director dbo:deathDate ?death . }
  OPTIONAL { ?director dbp:deathDate ?death2 . }
  OPTIONAL { ?director dbp:death_date ?death3 . }
  BIND(COALESCE(?death, ?death2, ?death3) AS ?deathDate)
